import { git } from './git.js';

export async function detectTamper() {
  try {
    const result = await git().raw(['rev-list', '--count', '--left-right', '@{u}...HEAD']);
    const [behindStr, aheadStr] = result.trim().split('\t');
    const behind = parseInt(behindStr || '0', 10);
    const ahead = parseInt(aheadStr || '0', 10);
    if (behind > 0 && ahead === 0) {
      console.log('⚠️  Local history behind upstream. Ensure no force-push tampering occurred.');
    }
  } catch {
    // upstream may not exist
  }
}
